local HS=game:GetService('HttpService')
local out={}
for _,c in ipairs(workspace:GetChildren()) do table.insert(out,c.Name..'('..c.ClassName..')') end
local plr=game.Players:GetPlayers()[1]
local pos=plr and plr.Character and plr.Character:GetPivot().Position
local prompts={}
for _,d in ipairs(workspace:GetDescendants()) do if d:IsA('ProximityPrompt') then table.insert(prompts,d:GetFullName()) if #prompts>8 then break end end end
return HS:JSONEncode({ws=out,pos=tostring(pos),prompts=prompts})

local HS=game:GetService('HttpService')
local ps=workspace:GetPartBoundsInBox(CFrame.new(-45,5,140),Vector3.new(60,12,80))
local out={}
for _,p in ipairs(ps) do if p.CanCollide and p.Name~='Terrain' then table.insert(out,(p:GetFullName():gsub('Workspace.Map.',''))..' pos='..tostring(p.Position)..' size='..tostring(p.Size)) end end
table.sort(out)
local o2={}
for i=1,math.min(#out,40) do o2[i]=out[i] end
return HS:JSONEncode({n=#out,parts=o2})

local HS=game:GetService('HttpService')
local ps=workspace:GetPartBoundsInBox(CFrame.new(-45,3.5,145),Vector3.new(50,5,50))
local out={}
for _,p in ipairs(ps) do if p.CanCollide and p.Name~='Terrain' then local top=p.Position.Y+p.Size.Y/2 table.insert(out,(p:GetFullName():gsub('Workspace.Map.',''))..' p='..tostring(p.Position)..' s='..tostring(p.Size)..' top='..top) end end
local mods={}
for _,d in ipairs(workspace:GetDescendants()) do if d:IsA('PathfindingModifier') or d:IsA('PathfindingLink') then table.insert(mods,d:GetFullName()..' '..tostring(d:IsA('PathfindingModifier') and d.PassThrough or '')) if #mods>10 then break end end end
table.sort(out)
local o2={} for i=1,math.min(#out,35) do o2[i]=out[i] end
return HS:JSONEncode({n=#out,parts=o2,mods=mods})
